struct Ref:H8SEmulator{void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc400&&a<0xce00)||(a>=0xfffd00&&a<0xffff00)||a==0xffffb2;}
struct RBus:H8SDevice{Ref&c;std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc<2||argc>3)return 77;bool boot=argc==3;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc400,0xa00);c->memmap(&x,0xfffd00,0x200);c->memmap(&x,0xffffb2,1);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerMidiServices rt;if((!boot&&!irq.bindVerifiedFirmware(*d,rom.data(),rom.size()))||!(boot?rt.bindBootResources(*d,rom.data(),rom.size()):rt.bindAll(*d,rom.data(),rom.size())))return 2;uint64_t graphs=0,phases=0,events=0,shorts=0;for(unsigned flags=boot?128:0;flags<256;++flags)for(unsigned kind=0;kind<2;++kind){if(!rt.reset())return 15;irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);for(uint32_t a=0xc400;a<0xce00;++a)c->memory[a]=d->memory[a]=uint8_t(a*19+flags);for(uint32_t a=0xfffd00;a<0xffff00;++a)c->memory[a]=d->memory[a]=uint8_t(a*7+flags);c->memory[0xffffb2]=d->memory[0xffffb2]=0x53;c->pc=c->makepc(kind?0x251a:0x9d0);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->ccr=uint8_t(flags);c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;if(!rt.startInit(kind?kstation::ControllerMidiInitRuntime::Kind::Initialize:kstation::ControllerMidiInitRuntime::Kind::SerialEnable))return 3;for(unsigned k=0;rt.initActive();++k){if(k>30000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=rt.nextInit(*d,irq);if(!cost){std::fprintf(stderr,"zero pc=%x\n",at);return 5;}for(unsigned b=0;b<cost;++b){auto before=d->cycles;auto r=rt.advanceInit(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}c->step();auto r=rt.advanceInit(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x kind=%u clocks=%llu/%llu io=%u/%u\n",at,kind,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x a=%x/%x v=%x/%x t=%llu/%llu\n",at,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}if(((c->ccr&128)!=0)!=(irq.mask()==kstation::ControllerInterruptRuntime::Mask::Disabled))return 9;events+=x.n;++phases;}if(c->getPC()!=0x7000||std::memcmp(c->memory+0xc400,d->memory+0xc400,0xa00)||std::memcmp(c->memory+0xfffd00,d->memory+0xfffd00,0x200)||c->memory[0xffffb2]!=d->memory[0xffffb2])return 10;++graphs;}if(boot){d->loadMemory(rom.data(),rom.size(),0x400000);d->memory[0x4009d0]^=1;if(rt.bindAll(*d,rom.data(),rom.size()))return 11;auto changed=rom;changed[0x9d0]^=1;if(rt.bindAll(*d,changed.data(),changed.size()))return 13;d->memory[0x4009d0]^=1;if(!rt.bindAll(*d,rom.data(),rom.size()))return 12;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
